        'Get-Process -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowTitle -ne $null} | ForEach-Object { [PSCustomObject]@{Name=$_.Name;PPID=$_.Id} }' | ConvertTo-Json -Depth 10
    ], capture_output=True, text=True)

    if result.returncode == 0 and result.stdout:
        import json
        # Parse JSON output and format as tree
        try:
            data = json.loads(result.stdout)
            tree = {'processes': data}
            return tree
        except:
            return {'error': result.stderr}
    else:
        return {'error': result.stderr}

